/* StreamSignal UI: fully offline, no analytics, accounts, external network calls or API keys. */
(() => {
  'use strict';
  const D=window.STREAM_DATA,C=window.StreamCore,E=C.engine(D),$=id=>document.getElementById(id);
  const colours={high:'#d94b3e',watch:'#b16e0c',routine:'#087e78',unknown:'#667889'};
  const cities=[['CO','Coimbra','Portugal'],['TO','Toulouse','France'],['GH','Ghent','Belgium'],['BE','Benevento','Italy'],['OS','Oslo','Norway']];
  const S={page:'impact',city:'all',date:D.dates.length-1,site:'C1',compare:'BN1',query:'',filter:'all',pageNo:0,budget:5,diversify:true,chart:'rain',savedOnly:false,saved:[],thresholds:{watch:85,high:95},resultStart:D.meta.replayStart,resultEnd:D.meta.weatherEnd,eventMetric:'all',eventSort:'duration',eventPage:0,reviews:{},forecastGroup:0,forecastDate:'2026-09-21'};
  try {const saved=JSON.parse(localStorage.getItem('streamsignal.preferences')||'{}');if(saved.reviews && typeof saved.reviews==='object' && !Array.isArray(saved.reviews))S.reviews=saved.reviews;if(Array.isArray(saved.saved))S.saved=saved.saved.filter(code=>D.sites.some(s=>s.code===code));}catch{}
  const W=window.StreamWorkbench,M=window.STREAM_MULTI;
  const mission={task:'rain_3',issue:'2026-02-02',region:'all',cut:30,budget:5,weight:0,distinct:true,recordSite:'C1',editRecord:null};
  const R=window.StreamResilience;
  const v4={issue:'2026-02-02',hazard:'rain',city:'CO',site:'C2',yellow:20,red:40,horizon:3,outcome:'all',timelinePage:0,tourStep:null};
  let citizenRecords=[];
  try{const a=JSON.parse(localStorage.getItem('streamsignal.citizen.v4')||'[]');if(Array.isArray(a))citizenRecords=a.filter(r=>r&&!R.validateCitizen(r,D));}catch{}
  let observations=[];
  try{const parsed=JSON.parse(localStorage.getItem('streamsignal.observations')||'[]');if(Array.isArray(parsed))observations=parsed.filter(r=>r&&D.sites.some(s=>s.code===r.site)&&!W.validateObservation(r));}catch{}
  const saveObservations=()=>{try{localStorage.setItem('streamsignal.observations',JSON.stringify(observations));return true;}catch{return false;}};
  function setMissionTask(key){if(!M.tasks[key])return;mission.task=key;const valid=W.dates(M.tasks[key]);if(!valid.includes(mission.issue))mission.issue=valid.at(-1);}
  const esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  const num=(v,n=1)=>v===null||v===undefined||!Number.isFinite(Number(v))?'—':Number(v).toFixed(n);
  const dateLabel=d=>new Date(d+'T12:00:00Z').toLocaleDateString('en-GB',{day:'numeric',month:'short',year:'numeric',timeZone:'UTC'});
  const metricName=m=>({rain:('3-day rainfall'),heat:('Daily maximum temperature'),dry:('Consecutive dry days')}[m]||'—');
  const driverName=m=>({rain:('Rainfall'),heat:('Heat'),dry:('Dry spell')}[m]||('Unavailable'));
  const levelName=l=>({high:('Review first'),watch:('Watch'),routine:('Routine'),unknown:('No data')}[l]);
  const pct=v=>v===null?'—':(Math.floor(v*10)/10).toFixed(1);
  const valueLabel=(m,v)=>v===null?'—':`${num(v,m==='dry'?0:1)} ${m==='rain'?'mm':m==='heat'?'°C':('days')}`;
  const pill=l=>`<span class="pill ${l}">${levelName(l)}</span>`;
  const firstReplay=D.dates.indexOf(D.meta.replayStart);
  let rows=[],rowByCode=new Map(),toastTimer;
  const siteFor=code=>D.sites.find(s=>s.code===code);
  const persist=()=>{try{localStorage.setItem('streamsignal.preferences',JSON.stringify({saved:S.saved,reviews:S.reviews}));}catch{}};
  function compute(){rows=C.rank(D.sites.map(s=>E.assess(s,S.date,S.thresholds)));rowByCode=new Map(rows.map(r=>[r.site.code,r]));}
  compute();S.site=rows[0].site.code;
  function filtered(){return rows.filter(r=>(S.city==='all'||r.site.city===S.city)&&(!S.savedOnly||S.saved.includes(r.site.code))&&(S.filter==='all'||r.level===S.filter)&&`${r.site.code} ${r.site.name} ${r.site.cityName}`.toLocaleLowerCase().includes(S.query.toLocaleLowerCase()));}
  const cityRows=()=>rows.filter(r=>S.city==='all'||r.site.city===S.city);
  function toast(message){$('toast').textContent=message;$('toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('toast').classList.remove('show'),3200);}
  function closeExport(){const modal=$('export-dialog');if(modal){const link=modal.querySelector('a[download]');if(link?.href.startsWith('blob:'))URL.revokeObjectURL(link.href);modal.remove();}if(exportFocus?.isConnected)exportFocus.focus();}
  let exportFocus=null;
  async function download(name,content,type='text/csv;charset=utf-8'){
    closeExport();exportFocus=document.activeElement;
    const dialog=document.createElement('dialog');dialog.id='export-dialog';dialog.setAttribute('aria-labelledby','export-title');
    dialog.innerHTML=`<div class="export-head"><div><span class="eyebrow">EXPORT PREVIEW</span><h2 id="export-title">Your file is ready.</h2><p>${esc(name)}</p></div><button class="secondary" data-action="close-export" aria-label="Close export preview">✕</button></div><div class="export-actions"><a class="primary" download="${esc(name)}">↓ Save file</a><span>Use Save file to download. The preview stays available below.</span></div><div class="export-content"></div>`;
    const url='data:'+type+','+encodeURIComponent(content);dialog.querySelector('a').href=url;
    const area=dialog.querySelector('.export-content');
    if(type.startsWith('text/html')){const frame=document.createElement('iframe');frame.title='Exported report preview';frame.setAttribute('sandbox','allow-scripts allow-modals');frame.srcdoc=content;area.appendChild(frame);}else{const label=document.createElement('label');label.textContent='File contents (select and copy if needed)';const field=document.createElement('textarea');field.readOnly=true;field.value=content;field.setAttribute('aria-label','Exported file contents');label.appendChild(field);area.appendChild(label);}
    document.body.appendChild(dialog);dialog.addEventListener('cancel',event=>{event.preventDefault();closeExport();});dialog.showModal();dialog.querySelector('a').focus();
    if(location.protocol==='http:'&&location.hostname==='127.0.0.1'){
      const saveLink=dialog.querySelector('a');saveLink.removeAttribute('href');saveLink.textContent='Preparing file…';saveLink.setAttribute('aria-busy','true');
      try{const response=await fetch('/api/export',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({name,content})});if(response.ok){const saved=await response.json();if(dialog.isConnected&&/^exported\/StreamSignal_[A-Za-z0-9_-]+\.(csv|html|json)$/.test(saved.url)){dialog.querySelector('a').href=saved.url;dialog.querySelector('.export-actions span').textContent='Saved in the local exported folder. Use Save file for another copy.';}}}catch{/* File preview and portable download remain available. */}finally{if(!saveLink.hasAttribute('href'))saveLink.href=url;saveLink.textContent='↓ Save file';saveLink.removeAttribute('aria-busy');}
    }
  }

  function controls(){return `<div class="controls"><label class="control">${('Region')}<select id="city" aria-label="${('Region')}"><option value="all">${('All five regions')}</option>${cities.map(([c,n])=>`<option value="${c}" ${S.city===c?'selected':''}>${n}</option>`).join('')}</select></label><span class="spacer"></span><label class="control">${('Replay date')}<input id="date" type="date" value="${D.dates[S.date]}" min="${D.meta.replayStart}" max="${D.meta.weatherEnd}"></label><button class="date-step" data-action="prev-date" aria-label="${('Previous day')}" ${S.date===firstReplay?'disabled':''}>←</button><button class="date-step" data-action="next-date" aria-label="${('Next day')}" ${S.date===D.dates.length-1?'disabled':''}>→</button><button class="secondary" data-action="rain-replay">${('Heavy-rain replay')} ↗</button></div>`;}
  function metrics(){const selected=cityRows(),high=selected.filter(r=>r.level==='high').length,groups=new Set(selected.map(r=>r.site.group)).size;return `<div class="metrics"><div class="metric"><div class="metric-label">${('Sites in view')}<span>◉</span></div><div class="metric-value">${selected.length}<span>/ 106</span></div><div class="metric-caption">${('Five urban water research regions')}</div></div><div class="metric"><div class="metric-label">${('Review first')}<span class="dot high"></span></div><div class="metric-value warn">${high}<span>${('sites')}</span></div><div class="metric-caption">${(`Any weather percentile ≥ ${S.thresholds.high}`)}</div></div><div class="metric"><div class="metric-label">${('Distinct weather series')}<span>≋</span></div><div class="metric-value">${groups}<span>${('groups')}</span></div><div class="metric-caption">${('Shared series are explicitly grouped')}</div></div><div class="metric"><div class="metric-label">${('Health sample coverage')}<span>⌁</span></div><div class="metric-value">${selected.filter(r=>r.site.health.length).length}<span>/ ${selected.length}</span></div><div class="metric-caption">${('Historical samples · 2023–2024')}</div></div></div>`;}
  function project(bounds,w=640,h=398){const [minx,miny,maxx,maxy]=bounds;const merc=y=>Math.log(Math.tan(Math.PI/4+Math.max(-85,Math.min(85,y))*Math.PI/360))*180/Math.PI;const ymax=merc(maxy),ymin=merc(miny);const scale=Math.min((w-70)/(maxx-minx),(h-65)/(ymax-ymin));return ([x,y])=>[(w-(maxx-minx)*scale)/2+(x-minx)*scale,(h-(ymax-ymin)*scale)/2+(ymax-merc(y))*scale];}
  function mapPanel(){let bounds=[-12,35,22,63],shown=cityRows();const local=S.city!=='all';if(local){const xs=shown.map(r=>r.site.lon),ys=shown.map(r=>r.site.lat);const px=Math.max(.014,(Math.max(...xs)-Math.min(...xs))*.18),py=Math.max(.012,(Math.max(...ys)-Math.min(...ys))*.18);bounds=[Math.min(...xs)-px,Math.min(...ys)-py,Math.max(...xs)+px,Math.max(...ys)+py];}const p=project(bounds);let paths='';if(!local){paths=window.STREAM_MAP.features.map(f=>{const polys=f.geometry.type==='MultiPolygon'?f.geometry.coordinates:[f.geometry.coordinates];return polys.map(poly=>`<path class="land" fill-rule="evenodd" d="${poly.map(ring=>ring.map((pt,i)=>{const [x,y]=p(pt);return `${i?'L':'M'}${x.toFixed(1)},${y.toFixed(1)}`;}).join('')+'Z').join('')}"/>`).join('');}).join('');}
    const grid=Array.from({length:7},(_,i)=>{const x=40+i*93;return `<line class="gridline" x1="${x}" y1="0" x2="${x}" y2="398"/>`;}).join('')+Array.from({length:6},(_,i)=>`<line class="gridline" x1="0" y1="${30+i*70}" x2="640" y2="${30+i*70}"/>`).join('');
    const labels=!local?[['FRANCE',2.5,46.6],['SPAIN',-3.6,39.5],['ITALY',12.3,43.5],['GERMANY',10.5,51],['NORWAY',7.5,62]].map(([label,x,y])=>{const q=p([x,y]);return `<text class="country-label" x="${q[0]}" y="${q[1]}" text-anchor="middle">${label}</text>`;}).join(''):'';
    const markers=local?shown.map(r=>{const [x,y]=p([r.site.lon,r.site.lat]);const selected=r.site.code===S.site;return `<g role="button" tabindex="0" aria-label="${esc(r.site.code+' '+r.site.name+', '+levelName(r.level))}" data-action="select-site" data-code="${r.site.code}"><title>${esc(r.site.code+' · '+r.site.name+' · '+levelName(r.level))}</title>${selected?`<circle cx="${x}" cy="${y}" r="15" fill="none" stroke="#4b7256" stroke-width="1.5"/>`:''}<circle cx="${x}" cy="${y}" r="${selected?8:6}" fill="${colours[r.level]}" stroke="#fff" stroke-width="2"/><text x="${x+10}" y="${y-8}" font-size="10" fill="#1b425b" paint-order="stroke" stroke="#e0ecf2" stroke-width="3">${r.site.code}</text></g>`;}).join(''):cities.map(([code,name])=>{const rr=rows.filter(r=>r.site.city===code);const s=rr[0];const location={CO:[-8.4103,40.2033],TO:[1.4442,43.6047],GH:[3.7174,51.0543],BE:[14.7868,41.1291],OS:[10.7522,59.9139]}[code];const [x,y]=p(location);return `<g role="button" tabindex="0" data-action="map-city" data-city="${code}" aria-label="${name}, ${rr.length} ${('sites')}"><title>${name} · ${rr.length} ${('sites. Select to explore.')}</title><circle cx="${x}" cy="${y}" r="23" fill="${colours[s.level]}" opacity=".12"/><circle cx="${x}" cy="${y}" r="15" fill="${colours[s.level]}" stroke="#fff" stroke-width="3"/><text x="${x}" y="${y+4}" text-anchor="middle" fill="white" font-size="10" font-weight="700">${rr.length}</text><text class="city-label" x="${x+23}" y="${y+4}">${name}</text></g>`;}).join('');
    return `<section class="panel"><div class="panel-header"><div><h2>${('A shared view of resilience')}</h2><p>${local?('Select a site to inspect its evidence'):('Select a region to explore its research sites')}</p></div>${local?`<button class="secondary" data-action="all-regions">↖ ${('Europe')}</button>`:`<span class="tag">106 ${('sites')}</span>`}</div><div class="map-wrap"><svg class="map-svg" viewBox="0 0 640 398" role="group" aria-label="${('Interactive research site map')}"><defs><clipPath id="mapclip"><rect width="640" height="398"/></clipPath></defs><g clip-path="url(#mapclip)">${grid}${paths}${labels}${markers}</g></svg><span class="map-badge">${local?('SITE COORDINATES · NO STREET LAYER'):('EUROPE / RESEARCH NETWORK')}</span><span class="map-note">${local?('Location plot · markers may overlap'):('Natural Earth · city colour = highest site index')}</span></div><div class="map-legend"><div class="legend-items">${['high','watch','routine','unknown'].map(l=>`<span><i class="dot ${l}"></i>${levelName(l)}</span>`).join('')}</div></div><div class="timeline"><div class="timeline-top"><b>${('Historical replay')}</b><span id="range-date">${dateLabel(D.dates[S.date])}</span></div><input id="timeline" type="range" min="${firstReplay}" max="${D.dates.length-1}" value="${S.date}" aria-label="${('Historical replay date')}" aria-valuetext="${D.dates[S.date]}"><div class="timeline-labels"><span>01 JAN 2025</span><span>${('Daily steps · missing days preserved')}</span><span>21 SEP 2026</span></div></div></section>`;
  }
  function detail(code,compact=false){const r=rowByCode.get(code),s=r.site,groupSize=D.sites.filter(x=>x.group===s.group).length;return `<section class="panel"><div class="detail-header"><div class="detail-heading"><div><div class="detail-kicker">${esc(s.cityName.toUpperCase())} / ${esc(s.code)}</div><h2>${esc(s.name)}</h2></div><button class="bookmark ${S.saved.includes(code)?'saved':''}" data-action="save-site" data-code="${code}" aria-pressed="${S.saved.includes(code)}" aria-label="${('Save site')} ${esc(s.code)}">${S.saved.includes(code)?'★':'☆'}</button></div><div class="detail-sub">${s.lat.toFixed(4)}° N · ${Math.abs(s.lon).toFixed(4)}° ${s.lon<0?'W':'E'} <span style="float:right">${pill(r.level)}</span></div></div><div class="detail-body"><div class="priority-box"><div class="score-ring" style="--score:${r.score??0};--color:${colours[r.level]}"><strong>${r.score===null?'—':Math.floor(r.score)}</strong></div><div class="priority-copy"><b>${('Weather screening index')}</b>${r.driver?('Led by ')+driverName(r.driver)+(' anomaly'):('No weather observations for this date')}<small>${('Relative to 2023–24 seasonal observations')}</small></div></div>${C.METRICS.map(m=>`<div class="signal-row"><span class="signal-label">${metricName(m)}</span><span class="value">${valueLabel(m,r.values[m])}</span><div class="signal-bar"><span style="width:${r.scores[m]??0}%;background:${r.scores[m]>=S.thresholds.high?colours.high:r.scores[m]>=S.thresholds.watch?colours.watch:colours.routine}"></span></div><div class="signal-foot"><span>${('Seasonal percentile')} ${pct(r.scores[m])}</span><span>n = ${r.counts[m]}</span></div></div>`).join('')}<p class="note">${('A screening priority, not a water-quality rating or a probability of harm.')}</p>${!r.complete?`<div class="callout amber">${('Incomplete weather evidence. Missing days are not filled; rolling rainfall and dry-spell signals may also be unavailable.')}</div>`:''}<div class="callout">${(`Weather group ${s.group+1} · ${groupSize} sites share this exact time series. These are not independent weather measurements.`)}</div>${!compact?`<div class="detail-footer"><button class="secondary" data-action="site-export" data-code="${code}">↓ ${('Export history')}</button><button class="secondary" data-action="compare-open" data-code="${code}">${('Compare site')} ⇄</button></div>`:''}</div></section>`;}
  function chart(code){const site=siteFor(code),m=S.chart,start=Math.max(0,S.date-59),part=E.derived[site.group].slice(start,S.date+1).map((r,i)=>({date:D.dates[start+i],v:r[m]}));const available=part.filter(x=>x.v!==null);const rawMin=available.length?Math.min(...available.map(r=>r.v)):0;const rawMax=available.length?Math.max(...available.map(r=>r.v)):1;const min=m==='heat'?Math.floor(rawMin/5)*5:0,max=Math.max(min+1,m==='heat'?Math.ceil(rawMax/5)*5:Math.ceil(rawMax*1.1));const x=i=>43+i*(610/(part.length-1||1)),y=v=>155-(v-min)/(max-min)*130;let path='',segments=[];part.forEach((r,i)=>{if(r.v===null){if(path)segments.push(path);path='';}else path+=(path?'L':'M')+x(i).toFixed(1)+','+y(r.v).toFixed(1);});if(path)segments.push(path);const line=m==='rain'?part.filter(r=>r.v!==null).map(r=>{const i=part.indexOf(r);return `<rect x="${x(i)-3}" y="${y(r.v)}" width="6" height="${155-y(r.v)}" rx="1.5" fill="#3c8ea7"><title>${r.date}: ${num(r.v)} mm</title></rect>`;}).join(''):segments.map(d=>`<path d="${d}" stroke="#0b6588" fill="none" stroke-width="2.5"/>`).join('');return `<section class="panel below chart"><div class="chart-head"><div><h2>${('The last 60 days')}</h2><p class="note" style="margin-top:4px">${esc(site.code)} · ${metricName(m)}</p></div><div class="tabs">${C.METRICS.map(k=>`<button data-action="chart" data-metric="${k}" class="${m===k?'active':''}" aria-pressed="${m===k}">${driverName(k)}</button>`).join('')}</div></div><svg class="chart-svg" role="img" aria-label="${esc(site.code+' '+metricName(m)+' '+part[0].date+' to '+part[part.length-1].date)}" viewBox="0 0 680 190">${[0,.5,1].map(f=>`<line class="chart-grid" x1="43" x2="653" y1="${155-f*130}" y2="${155-f*130}"/><text class="chart-axis" x="34" y="${159-f*130}" text-anchor="end">${num(min+f*(max-min),m==='dry'?0:1)}</text>`).join('')}${line}<text class="chart-axis" x="43" y="181">${part[0].date}</text><text class="chart-axis" x="653" y="181" text-anchor="end">${part[part.length-1].date}</text></svg><p class="chart-note">Text summary: ${available.length} observed days; ${part.length-available.length} missing. Range ${num(rawMin)} to ${num(rawMax)} ${m==='heat'?'°C':m==='rain'?'mm':'days'}.</p><details class="prose padded"><summary>Read chart values as a table</summary><div class="table-scroll"><table><thead><tr><th>Date</th><th>${metricName(m)}</th></tr></thead><tbody>${part.map(r=>`<tr><td>${r.date}</td><td>${r.v===null?'Missing':num(r.v)}</td></tr>`).join('')}</tbody></table></div></details><div class="chart-note">${('Gaps remain blank. Use “Export history” for exact values. Rainfall is a trailing three-day total, not daily rain.')}</div></section>`;}
  function historicEvidence(code){const s=siteFor(code),h=s.health.filter(r=>r.samplingDate.slice(0,10)<=D.dates[S.date]).sort((a,b)=>b.samplingDate.localeCompare(a.samplingDate))[0],n=s.nitrate.filter(r=>r.date<=D.dates[S.date]).sort((a,b)=>b.date.localeCompare(a.date))[0],u=s.urban;const age=h?Math.floor((Date.parse(D.dates[S.date])-Date.parse(h.samplingDate.slice(0,10)))/86400000):null;return `<section class="panel below"><div class="panel-header"><div><h2>${('Ground evidence')}</h2><p>${('Kept separate from the weather screening index')}</p></div><span class="tag">${('Historical')}</span></div><div class="detail-body"><div class="evidence-block"><h3>${('Health risk sample')}</h3>${h?`<div class="evidence-list"><span>${('Sample date')}</span><b>${h.samplingDate.slice(0,10)}</b><span>${('Sample age at replay date')}</span><b>${age} ${('days')}</b><span>${('Overall scaled score')}</span><b>${num(h.healthRiskScore,4)}</b><span>${('Pathogen / faecal / ARG')}</span><b>${num(h.scaledPathogenRisk,3)} / ${num(h.scaledFecalRisk,3)} / ${num(h.scaledArgRisk,3)}</b></div><p>${('These source-platform scores describe an old sample. They cannot establish present water safety.')}</p>`:`<p>${('No health risk sample is available for this site in the snapshot.')}</p>`}</div><div class="evidence-block"><h3>${('Nitrate indicator')}</h3><div class="evidence-list"><span>${('Source value · statusOfNitrate')}</span><b>${n?num(n.statusOfNitrate,4):'—'}</b><span>${('Sample date')}</span><b>${n?n.date:('Unavailable')}</b></div><p>${('Units and classification thresholds have not been verified. No concentration or safety category is inferred.')}</p></div><div class="evidence-block"><h3>${('Urban context')}</h3><div class="evidence-list"><span>${('Urban cover · 500 m buffer')}</span><b>${u?num(u.urbanPct500m,1)+'%':'—'}</b><span>${('Impervious cover · 500 m buffer')}</span><b>${u?num(u.imperviousPct500m,1)+'%':'—'}</b><span>${('Sampling date')}</span><b>${u?.samplingDate?u.samplingDate.slice(0,10):('Not supplied')}</b></div><p>${('Context only; not added to the weather index. Buffer sizes and field names follow the source.')}</p></div></div></section>`;}
  function table(){const rr=filtered(),pageSize=10,pages=Math.max(1,Math.ceil(rr.length/pageSize));S.pageNo=Math.min(S.pageNo,pages-1);const slice=rr.slice(S.pageNo*pageSize,(S.pageNo+1)*pageSize);return `<section class="panel below"><div class="panel-header wrap-mobile"><div><h2>${('Where to look next')}</h2><p>${('Sorted by weather index · ties use site code')}</p></div><div class="table-toolbar"><label class="toggle-label"><input id="saved-only" type="checkbox" ${S.savedOnly?'checked':''}>${('Saved')}</label><input class="search" id="search" value="${esc(S.query)}" placeholder="${('Search site or city…')}" aria-label="${('Search sites')}"><select id="level-filter" aria-label="${('Priority filter')}" style="font-size:11px;padding:9px"><option value="all">${('All priorities')}</option>${['high','watch','routine','unknown'].map(l=>`<option value="${l}" ${S.filter===l?'selected':''}>${levelName(l)}</option>`).join('')}</select></div></div><div class="table-scroll"><table><thead><tr><th>${('SITE')}</th><th>${('REGION')}</th><th>${('INDEX')}</th><th>${('PRIORITY')}</th><th>${('MAIN SIGNAL')}</th><th>${('WEATHER GROUP')}</th><th>${('HEALTH SAMPLE')}</th></tr></thead><tbody>${slice.map(r=>`<tr class="${r.site.code===S.site?'selected':''}"><td><button class="site-link" data-action="select-site" data-code="${r.site.code}"><b>${esc(r.site.code)} ${S.saved.includes(r.site.code)?'★':''}</b><small>${esc(r.site.name)}</small></button></td><td>${r.site.cityName}</td><td><span class="index-num">${r.score===null?'—':pct(r.score)}</span>${!r.complete?' *':''}</td><td>${pill(r.level)}</td><td>${driverName(r.driver)}</td><td>${r.site.group+1}</td><td>${r.site.health.length?r.site.health[0].samplingDate.slice(0,10):('No sample')}</td></tr>`).join('')}</tbody></table>${!slice.length?`<div class="empty">${('No sites match these filters. Try another region, priority or search.')}</div>`:''}</div><div class="table-footer"><span>${rr.length?(`${S.pageNo*pageSize+1}–${Math.min((S.pageNo+1)*pageSize,rr.length)} of ${rr.length} sites`):('0 sites')} · ${('* incomplete weather')}</span><div class="pager"><button class="secondary" data-action="page-prev" ${!S.pageNo?'disabled':''}>←</button><button class="secondary" data-action="page-next" ${S.pageNo>=pages-1?'disabled':''}>→</button></div></div></section>`;}
  function overview(){return `${insightStrip()}${metrics()}${controls()}${D.meta.missingDates.includes(D.dates[S.date])?`<div class="callout amber" style="margin:0 0 18px">${('This date is absent from the source for every site. No priority can be calculated; it is not a day with zero risk.')}</div>`:''}<div class="dashboard-grid"><div>${mapPanel()}${chart(S.site)}</div><div>${detail(S.site)}${historicEvidence(S.site)}</div></div>${table()}`;}
  function planView(){const candidates=cityRows().filter(r=>!S.savedOnly||S.saved.includes(r.site.code)),picked=C.plan(candidates,S.budget,S.diversify);return `${controls()}<section class="panel"><div class="cover-head"><div class="eyebrow">${('A SMALLER, MORE USEFUL FIELD LIST')}</div><h2>Sampling candidates</h2><p class="subtitle" style="margin-top:8px">${('Use weather anomalies to focus a human review. Avoid spending the entire visit budget on identical weather evidence.')}</p></div><div class="plan-config"><label>${('Visit budget')}<select id="budget">${[3,5,8,10,15,21].map(v=>`<option ${v===S.budget?'selected':''}>${v}</option>`).join('')}</select></label><label><input type="checkbox" id="diversify" ${S.diversify?'checked':''}>${('One site per weather group')}</label><label><input type="checkbox" id="saved-only" ${S.savedOnly?'checked':''}>${('Saved sites only')}</label><button class="secondary" data-action="field-brief">↓ Review brief</button><button class="primary" data-action="plan-export">↓ ${('Export field plan')}</button></div><div class="plan-intro">${(`${picked.length} of ${S.budget} visits filled · ${new Set(picked.map(r=>r.site.group)).size} distinct weather groups. Selection uses the weather index, then site code. It does not optimize travel or prove that these sites are unsafe.`)}${picked.length<S.budget?' '+('The list stays shorter when there are not enough eligible groups or sites.'):''}</div>${picked.length?picked.map((r,i)=>`<div class="plan-item"><span class="plan-number">${String(i+1).padStart(2,'0')}</span><div class="plan-item-main"><h3><button class="site-link" data-action="select-site" data-code="${r.site.code}">${esc(r.site.code+' · '+r.site.name)}</button></h3><p>${r.site.cityName} · ${('Weather group')} ${r.site.group+1} · ${driverName(r.driver)} ${('percentile')} ${pct(r.score)}</p><p>${('Suggested task: verify local conditions and consider a fresh sample.')}</p>${fieldReview(r)}</div><div>${pill(r.level)}<div class="score" style="margin-top:6px;text-align:right">${Math.floor(r.score)}</div></div></div>`).join(''):`<div class="empty">${('No eligible sites. Save sites in the overview, widen the region, or choose a date with observations.')}</div>`}<div class="prose"><h3>${('Before a field visit')}</h3><p>${('Confirm local access and sampling procedures with the responsible team. This prototype is an analyst planning aid, not an official alert or a safety instruction.')}</p></div></section>`;}
  function compareView(){const opts=selected=>D.sites.map(s=>`<option value="${s.code}" ${s.code===selected?'selected':''}>${esc(s.cityName+' / '+s.code+' · '+s.name)}</option>`).join('');const a=siteFor(S.site),b=siteFor(S.compare);return `${controls()}<div class="compare-selects"><label>${('Site A')}<select id="compare-a">${opts(S.site)}</select></label><label>${('Site B')}<select id="compare-b">${opts(S.compare)}</select></label></div>${a.group===b.group?`<div class="callout amber" style="margin:0 0 17px">${('These sites share the same weather series. Their weather screening indices will be identical; differences in historical samples should not be attributed to weather alone.')}</div>`:''}<div class="compare-grid"><div>${detail(S.site,true)}${historicEvidence(S.site)}</div><div>${detail(S.compare,true)}${historicEvidence(S.compare)}</div></div>`;}
  function evidenceView(){return window.StreamBulletin.limits()+`<div class="doc-grid"><section class="panel prose"><div class="eyebrow">${('SHOW THE WORK')}</div><h2>Methods and reference data</h2><p>${('StreamSignal turns the downloaded OneAquaHealth snapshot into a retrospective monitoring and field-planning workspace. The descriptive screen does not estimate illness or certify water quality. The Multi-hazard lab evaluates eight three- and seven-day weather tasks with temporal and city-exclusion checks. The original one-day experiment remains as a benchmark. Mission control turns a weather signal into a proposed field investigation.')}</p><h3>01 · ${('Three observable signals')}</h3><ul><li>${('Rain: rainfall total for the selected day and its two preceding calendar days. All three must be observed.')}</li><li>${('Heat: the selected day’s maximum 2 m air temperature.')}</li><li>${('Dry spell: consecutive days with daily rainfall below 1 mm, ending on the selected day. This is an operational convention, not a validated drought definition.')}</li></ul><h3>02 · ${('Compare like seasons')}</h3><p>${('Each signal is compared with the same weather group’s 2023–2024 observations within ±30 calendar days of the selected day-of-year. A circular 366-day calendar handles year-end and leap days. The baseline is fixed before replay begins in 2025.')}</p><div class="formula">${('Percentile = 100 × (values below + 0.5 × ties) / valid baseline count')}<br><br>${('Screening index = maximum of the three available percentiles')}</div><p>${('Midrank ties prevent identical zero-rain observations from all being scored as extreme. The index is a descriptive ranking, not a probability. Baseline count is shown for each signal.')}</p><h3>03 · ${('Keep missing evidence visible')}</h3><p>${('The source has no weather rows on 4 or 27 August 2026. These days remain missing. A missing day invalidates a three-day rainfall window. Dry-spell length remains unknown after a gap until a day with ≥1 mm rainfall resets the run.')}</p><p>${('If one or two signals are available, the maximum uses only those signals and the site is marked incomplete. If all are missing, the site is unscored and excluded from the field plan.')}</p><h3>04 · ${('Make thresholds inspectable')}</h3><p>${('The default thresholds of 85 and 95 are prototype choices, not calibrated health or regulatory limits. Taking the maximum of three percentiles can flag more than 5% of days at a threshold of 95.')}</p><form id="threshold-form"><div class="thresholds"><label>${('Watch at ≥')}<input type="number" id="watch-threshold" min="0" max="99" step="1" value="${S.thresholds.watch}" required></label><label>${('Review first at ≥')}<input type="number" id="high-threshold" min="1" max="100" step="1" value="${S.thresholds.high}" required></label></div><p class="error" id="threshold-error" role="alert"></p><button class="primary" type="submit">${('Apply thresholds')}</button> <button class="secondary" type="button" data-action="reset-thresholds">${('Reset 85 / 95')}</button></form></section><div><section class="panel prose"><h2>${('Data, with its limits attached')}</h2><div class="evidence-list"><span>${('Research sites')}</span><b>106</b><span>${('Distinct weather series')}</span><b>21</b><span>${('Source weather records')}</span><b>143,948</b><span>${('Weather period')}</span><b>2023-01-01 → 2026-09-21</b><span>${('Health risk samples')}</span><b>96</b><span>${('Nitrate records')}</span><b>100</b><span>${('Urban context records')}</span><b>104</b><span>${('Download date')}</span><b>2026-09-28</b></div><div class="callout amber">${('Health labels are too sparse for a defensible disease-prediction claim. Historical health and urban context are displayed separately and do not enter the screening index.')}</div><p>${('Shared weather series are grouped by exact equality across all ten weather fields and all dates. Group identity is a redundancy check, not a claim about the upstream weather grid or sensor.')}</p><p>${('No satellite observations are included. Public access is not a verified redistribution licence; confirm OneAquaHealth terms before publishing the bundled snapshot.')}</p><button class="secondary" data-action="audit-export">↓ ${('Download data audit')}</button></section><section class="panel prose section-gap"><h2>${('Trace every source')}</h2><div class="source-links"><a href="https://apps.oneaquahealth.eu/resmap/" target="_blank" rel="noopener">OneAquaHealth Resilience Map ↗</a><a href="https://oneaquahealth-ieee-hackathon.devpost.com/" target="_blank" rel="noopener">IEEE Global Hackathon · Track 6 ↗</a><a href="https://www.naturalearthdata.com/" target="_blank" rel="noopener">Natural Earth · ${('public-domain country outlines')} ↗</a><a href="docs/METHODS.md">${('Methodology and limitations')} ↗</a><a href="docs/PROJECT_DESCRIPTION.md">${('English project description')} ↗</a></div></section><section class="panel prose section-gap"><h2>${('Designed to work offline')}</h2><p>${('No account, cloud model or API key is needed. Site bookmarks and review notes are saved in this browser. The app does not send alerts or transmit data to external services. The optional local preview server saves generated exports on this computer. Exports include the replay date, baseline and method.')}</p></section></div></div>`;}
  const resultCache=new Map();
  const reviewKey=code=>`${D.dates[S.date]}:${code}`;
  function getResults(){
    const key=[S.city,S.resultStart,S.resultEnd,S.thresholds.high,S.budget].join('|');
    if(!resultCache.has(key))resultCache.set(key,window.StreamAnalytics.analyze(D,window.STREAM_REPLAY,{city:S.city,start:S.resultStart,end:S.resultEnd,threshold:S.thresholds.high,budget:S.budget}));
    return resultCache.get(key);
  }
  function resultControls(){return `<div class="analysis-controls"><label>Region<select id="city" aria-label="Region"><option value="all">All five regions</option>${cities.map(([c,n])=>`<option value="${c}" ${S.city===c?'selected':''}>${n}</option>`).join('')}</select></label><label>From<input id="result-start" aria-label="Analysis start date" type="date" min="${D.meta.replayStart}" max="${D.meta.weatherEnd}" value="${S.resultStart}"></label><label>Through<input id="result-end" aria-label="Analysis end date" type="date" min="${D.meta.replayStart}" max="${D.meta.weatherEnd}" value="${S.resultEnd}"></label><label>Flag at index<select id="analysis-threshold">${[...new Set([85,90,95,98,99,S.thresholds.high])].sort((a,b)=>a-b).map(v=>`<option value="${v}" ${v===S.thresholds.high?'selected':''}>≥ ${v}</option>`).join('')}</select></label><label>Visit budget<select id="budget">${[3,5,8,10,15,21].map(v=>`<option ${v===S.budget?'selected':''}>${v}</option>`).join('')}</select></label><div class="quick-ranges"><button class="secondary" data-action="result-period" data-period="2025">2025</button><button class="secondary" data-action="result-period" data-period="2026">2026</button><button class="secondary" data-action="result-period" data-period="all">Full replay</button></div></div>`;}
  function comparisonBars(r){const c=r.comparison,items=[['Top-ranked sites',c.naiveMeanGroups,'#53758b'],['Uniform random sites¹',c.randomExpectedGroups,'#3c87b5'],['One per weather group',c.diverseMeanGroups,'#067f8b']];return `<div class="comparison-bars">${items.map(([label,value,color])=>`<div class="comparison-bar"><div><b>${label}</b><span>${num(value,2)} groups</span></div><div class="bar-track"><span style="width:${value===null?0:100*value/S.budget}%;background:${color}"></span></div></div>`).join('')}</div><p class="note">¹ Exact expected coverage for uniform random site selection without replacement. It is not a simulated field trial. All strategies have the same maximum visit budget.</p>`;}
  function monthlyChart(r){const vals=r.monthly,w=750,h=205,max=Math.max(30,...vals.map(v=>v.flaggedPct||0))*1.12,step=650/Math.max(1,vals.length);return `<svg class="result-chart" viewBox="0 0 ${w} ${h}" role="img" aria-label="Monthly percentage of valid weather-group days at or above the screening threshold">${[0,.5,1].map(f=>`<line x1="45" y1="${165-f*135}" x2="713" y2="${165-f*135}" class="chart-grid"/><text x="35" y="${169-f*135}" text-anchor="end" class="chart-axis">${Math.round(f*max)}%</text>`).join('')}${vals.map((m,i)=>{const v=m.flaggedPct||0;return `<g><title>${m.month}: ${num(m.flaggedPct,1)}%, ${m.flagged} / ${m.valid} group-days</title><rect x="${50+i*step}" y="${165-135*v/max}" width="${Math.max(4,step-6)}" height="${135*v/max}" rx="3" fill="${v>=25?'#0b547d':'#07858d'}"/>${i%Math.max(1,Math.ceil(vals.length/9))===0?`<text x="${50+i*step+step/2}" y="188" text-anchor="middle" class="chart-axis">${m.month.slice(2)}</text>`:''}</g>`;}).join('')}</svg><details class="prose padded"><summary>Read monthly chart values as a table</summary><div class="table-scroll"><table><thead><tr><th>Month</th><th>Flagged / valid group-days</th><th>Percentage</th></tr></thead><tbody>${vals.map(m=>`<tr><td>${m.month}</td><td>${m.flagged} / ${m.valid}</td><td>${num(m.flaggedPct)}%</td></tr>`).join('')}</tbody></table></div></details>`;}
  function resultsView(){const r=getResults(),c=r.comparison,ratio=c.naiveMeanGroups?c.diverseMeanGroups/c.naiveMeanGroups:null;return `${resultControls()}${!c.validDays?'<div class="callout amber" style="margin-bottom:16px">No weather observations are available in this window. Results are unscored, not zero risk.</div>':''}<section class="results-hero"><div><span class="eyebrow">THE FINDING / ${c.validDays} ELIGIBLE REPLAY DAYS</span><h2>More distinct weather evidence.<br>A visible priority tradeoff.</h2><p>With up to ${S.budget} visits, weather-aware selection covers <b>${num(c.diverseMeanGroups,2)} groups</b> instead of <b>${num(c.naiveMeanGroups,2)}</b> on average. The mean selected screening index moves from <b>${num(c.naiveMeanIndex,2)}</b> to <b>${num(c.diverseMeanIndex,2)}</b>.</p><div class="hero-actions"><button class="primary" data-action="analysis-report">↓ Download analysis report</button><button class="secondary" data-action="results-csv">↓ Daily comparison CSV</button></div></div><div class="result-ratio"><strong>${num(ratio,2)}<span>×</span></strong><b>distinct-series coverage</b><small>Relative to top-ranked site selection.<br>Not pollution-detection accuracy.</small></div></section><div class="metrics results-metrics"><div class="metric"><div class="metric-label">Valid weather-group days</div><div class="metric-value">${r.counts.groupDays.toLocaleString('en-US')}</div><div class="metric-caption">${r.scope.groupCount} groups · ${r.counts.calendarDays} calendar days</div></div><div class="metric"><div class="metric-label">Days meeting the screen</div><div class="metric-value">${num(r.flaggedPct,1)}<span>%</span></div><div class="metric-caption">${r.counts.flaggedGroupDays.toLocaleString('en-US')} / ${r.counts.groupDays.toLocaleString('en-US')} valid group-days</div></div><div class="metric"><div class="metric-label">Mean priority tradeoff</div><div class="metric-value">${num(c.meanIndexTradeoff,2)}<span>points</span></div><div class="metric-caption">Top-ranked index minus diverse-plan index</div></div><div class="metric"><div class="metric-label">Days with less repeated evidence</div><div class="metric-value">${c.reducedRedundancyDays}<span>/ ${c.validDays}</span></div><div class="metric-caption">More distinct groups than the top-ranked plan</div></div></div><div class="results-grid"><section class="panel"><div class="panel-header"><div><h2>Same budget. Different information.</h2><p>Average distinct series represented in the visit list</p></div><span class="tag">${S.budget} VISITS MAX</span></div><div class="prose">${comparisonBars(r)}<div class="comparison-facts"><div><span>Top-ranked mean index</span><b>${num(c.naiveMeanIndex,2)}</b></div><div><span>Diverse mean index</span><b>${num(c.diverseMeanIndex,2)}</b></div><div><span>Diverse mean visits used</span><b>${num(c.diverseMeanVisits,2)}</b></div></div></div></section><section class="panel"><div class="panel-header"><div><h2>Threshold sensitivity</h2><p>Measured over the same valid group-days</p></div></div><div class="prose sensitivity">${r.sensitivity.map(s=>`<div><b>≥ ${s.threshold}</b><div class="bar-track"><span style="width:${s.flaggedPct??0}%;background:${s.threshold===S.thresholds.high?'#0c4268':'#158797'}"></span></div><strong>${num(s.flaggedPct,1)}%</strong></div>`).join('')}<p class="note">Three signals are combined by their maximum. A 95 threshold does not mean that 5% of days will be flagged. Thresholds are prototype choices, not calibrated safety limits.</p></div></section></div><section class="panel section-gap"><div class="panel-header"><div><h2>Screening activity through time</h2><p>Percentage of observed weather-group days; counts are not independent trials</p></div><button class="secondary" data-action="monthly-csv">↓ Monthly data</button></div><div class="prose">${monthlyChart(r)}<div class="chart-note">${r.counts.missingGroupDays} group-days are entirely missing and excluded from percentage denominators. ${r.counts.incompleteGroupDays} scored group-days have fewer than three usable signals.</div></div></section><section class="panel section-gap"><div class="panel-header"><div><h2>Where the signals concentrate</h2><p>Group-level summaries avoid counting identical site weather repeatedly</p></div><button class="secondary" data-action="groups-csv">↓ Group data</button></div><div class="table-scroll"><table><thead><tr><th>REGION / WEATHER GROUP</th><th>SITES SHARING INPUT</th><th>VALID DAYS</th><th>FLAGGED DAYS</th><th>FLAGGED RATE</th><th>INCOMPLETE</th></tr></thead><tbody>${[...r.groups].sort((a,b)=>(b.flaggedPct||0)-(a.flaggedPct||0)).map(g=>`<tr><td><button class="site-link" data-action="group-focus" data-group="${g.group}"><b>${g.cityName}</b><small>Group ${g.group+1} ↗</small></button></td><td title="${g.siteCodes.join(', ')}">${g.siteCodes.length} sites</td><td>${g.valid}</td><td>${g.flagged}</td><td><span class="table-rate">${num(g.flaggedPct,1)}%<span style="width:${g.flaggedPct||0}%"></span></span></td><td>${g.incomplete} days</td></tr>`).join('')}</tbody></table></div></section><div class="result-interpretation"><h3>Read the result correctly</h3><p>The measured gain is coverage of <b>different input time series</b>. It is not measured sampling efficiency, ecological benefit or disease-prediction performance. Series may still be correlated. Plans may use fewer visits when a region has fewer groups than the budget; the number of visits is shown above.</p><a href="docs/RESULTS.md">Read the complete experiment and denominators ↗</a></div>`;}
  function eventList(){const r=getResults();return r.episodes.filter(e=>S.eventMetric==='all'||e.driver===S.eventMetric).sort((a,b)=>S.eventSort==='recent'?b.start.localeCompare(a.start)||a.group-b.group:S.eventSort==='peak'?b.peakIndex-a.peakIndex||b.days-a.days:b.days-a.days||b.peakIndex-a.peakIndex);}
  function eventsView(){const r=getResults(),list=eventList(),size=12,pages=Math.max(1,Math.ceil(list.length/size));S.eventPage=Math.min(S.eventPage,pages-1);return `${resultControls()}<div class="event-intro"><div><span class="eyebrow">EXPLORATORY CASES / SOURCE OBSERVATIONS</span><h2>Start with an observed extreme.</h2><p>These are historical weather observations, not verified flood, drought or contamination events.</p></div><button class="secondary" data-action="events-csv">↓ All matching episodes</button></div><div class="extreme-cards">${Object.entries(r.extremes).map(([m,x])=>`<button class="extreme-card ${m}" data-action="open-extreme" data-metric="${m}" ${!x?'disabled':''}><span>${metricName(m)}</span><strong>${x?num(x.value,m==='dry'?0:2):'—'}<small>${m==='rain'?'mm':m==='heat'?'°C':'days'}</small></strong><p>${x?esc(x.cityName)+' · '+x.date:'No observed value in this window'}</p><b>Inspect this day <span>↗</span></b></button>`).join('')}</div><section class="panel section-gap"><div class="panel-header wrap-mobile"><div><h2>Screening episode catalogue <span class="count-chip">${list.length}</span></h2><p>Consecutive flagged days within one weather group; missing days break a run</p></div><div class="table-toolbar"><label class="control">Peak driver<select id="event-metric">${[['all','All signals'],['rain','Rainfall'],['heat','Heat'],['dry','Dry spell']].map(([v,l])=>`<option value="${v}" ${S.eventMetric===v?'selected':''}>${l}</option>`).join('')}</select></label><label class="control">Sort<select id="event-sort"><option value="duration" ${S.eventSort==='duration'?'selected':''}>Longest first</option><option value="recent" ${S.eventSort==='recent'?'selected':''}>Most recent</option><option value="peak" ${S.eventSort==='peak'?'selected':''}>Highest peak</option></select></label></div></div><div class="table-scroll"><table><thead><tr><th>REGION / GROUP</th><th>PERIOD</th><th>DURATION</th><th>PEAK INDEX</th><th>PEAK DRIVER</th><th>EVIDENCE</th><th></th></tr></thead><tbody>${list.slice(S.eventPage*size,(S.eventPage+1)*size).map(e=>`<tr><td><b>${e.cityName}</b><small class="cell-sub">Weather group ${e.group+1} · ${e.siteCodes.length} sites</small></td><td>${e.start}<small class="cell-sub">through ${e.end}</small></td><td><b>${e.days}</b> days</td><td><b>${num(e.peakIndex,1)}</b></td><td>${driverName(e.driver)}</td><td>${e.incompleteDays?`<span class="pill watch">${e.incompleteDays} incomplete days</span>`:'<span class="pill routine">Complete signals</span>'}${e.leftCensored||e.rightCensored?'<small class="cell-sub">Window / missing-data boundary</small>':''}</td><td><button class="secondary" data-action="open-episode" data-episode="${e.id}">Replay peak ↗</button></td></tr>`).join('')}</tbody></table></div>${!list.length?'<div class="empty">No episodes meet these filters. Choose a wider period or another threshold.</div>':''}<div class="table-footer"><span>${list.length?`${S.eventPage*size+1}–${Math.min((S.eventPage+1)*size,list.length)} of ${list.length}`:'0'} episodes</span><div class="pager"><button class="secondary" data-action="event-prev" ${!S.eventPage?'disabled':''}>←</button><button class="secondary" data-action="event-next" ${S.eventPage>=pages-1?'disabled':''}>→</button></div></div></section><div class="result-interpretation"><h3>An episode is a screen, not an incident.</h3><p>Runs combine days where at least one weather percentile exceeds the selected threshold. The leading signal may change within a run. “Peak driver” describes the day with the highest index, and ties follow rainfall, heat, then dry spell. A report-window edge or an adjacent missing day marks a censored boundary.</p></div>`;}
  function fieldReview(r){const stored=S.reviews[reviewKey(r.site.code)]||{},status=stored.status||'Not reviewed';return `<details class="review-editor"><summary>${esc(status)} · Add a review note</summary><div><label>Status<select class="review-status" data-code="${r.site.code}" aria-label="Review status ${r.site.code}">${['Not reviewed','Visit planned','Sample requested','Reviewed'].map(v=>`<option ${v===status?'selected':''}>${v}</option>`).join('')}</select></label><label>Analyst note<textarea class="review-note" data-code="${r.site.code}" maxlength="1000" rows="3" aria-label="Analyst note ${r.site.code}" placeholder="Record what should be verified in the field…">${esc(stored.note||'')}</textarea></label><small>Saved in this browser for ${D.dates[S.date]}. Not a source measurement.</small></div></details>`;}
  function insightStrip(){const total=window.STREAM_RESULTS_SUMMARY;if(!total)return '';return `<div class="insight-strip"><div><span class="insight-icon">↗</span><p><b>There is a result behind this map.</b><span>Five visits cover ${num(total.diverseMeanGroups,2)} distinct weather groups instead of ${num(total.naiveMeanGroups,2)} in the full replay comparison.</span></p></div><button data-action="navigate" data-page="results">Explore results <span>→</span></button></div>`;}
  function exportRows(name,records){const headers=Object.keys(records[0]||{});download(name,C.csv([headers,...records.map(r=>headers.map(k=>Array.isArray(r[k])?r[k].join(';'):r[k]!==null&&typeof r[k]==='object'?JSON.stringify(r[k]):r[k]))]));}
  function showObservation(group,date,metric){const candidates=D.sites.filter(s=>s.group===group&&(S.city==='all'||s.city===S.city));const site=candidates[0]||D.sites.find(s=>s.group===group);S.site=site.code;S.city=site.city;S.page='overview';S.query='';S.filter='all';S.savedOnly=false;S.chart=metric||'rain';setDate(D.dates.indexOf(date));}

  function forecastView(){
    const F=window.STREAM_FORECAST,m=F.test.logistic,b=F.test.seasonal,ci=F.brierDifferenceInterval;
    const groups=D.series.map((_,group)=>({group,site:D.sites.find(s=>s.group===group)}));
    const selected=F.predictions.find(p=>p[0]===S.forecastGroup&&p[2]===S.forecastDate);
    const outcome=selected?(selected[5]>=m.threshold?(selected[4]?'True positive':'False positive'):(selected[4]?'False negative':'True negative')):'';
    return `<section class="results-hero"><div><span class="eyebrow">RETROSPECTIVE FORECAST EXPERIMENT / 2026 TEMPORAL TEST</span><h2>Next-day rainfall benchmark</h2><p>A transparent logistic model estimates whether <b>next-day recorded rainfall reaches 10 mm</b>. It uses only weather available through the issue day. All results below are from held-out 2026 observations.</p><div class="hero-actions"><a class="primary" href="results/forecast_report.html" download>↓ Download model report</a><a class="secondary" href="results/forecast_test_predictions.csv" download>↓ Every test prediction</a></div></div><div class="result-ratio"><strong>${num(100*F.brierSkill,1)}<span>%</span></strong><b>lower probability error</b><small>Brier score relative to a training-only seasonal baseline.<br>Same regions, later dates. Not a live warning.</small></div></section>
    <div class="split-grid">${[['train','TRAIN / FIT WEIGHTS'],['validation','VALIDATE / SELECT SETTINGS'],['test','TEST / REPORT ONCE']].map(([key,label])=>`<div><span class="eyebrow">${label}</span><h3>${F.split[key].targetStart.slice(0,4)}${key==='train'?'–2024':''}</h3><b>${F.split[key].rows.toLocaleString('en-US')} group-days</b><p>${F.split[key].events} events · ${num(100*F.split[key].eventRate,2)}%<br>${F.split[key].targetStart} — ${F.split[key].targetEnd}</p></div>`).join('')}</div>
    <div class="metrics"><div class="metric"><div class="metric-label">ROC AUC</div><div class="metric-value">${num(m.rocAuc,3)}</div><div class="metric-caption">Ranking discrimination · baseline ${num(b.rocAuc,3)}</div></div><div class="metric"><div class="metric-label">Average precision</div><div class="metric-value">${num(m.averagePrecision,3)}</div><div class="metric-caption">Test event frequency ${num(100*m.eventRate,2)}%</div></div><div class="metric"><div class="metric-label">Precision at frozen threshold</div><div class="metric-value">${num(100*m.precision,1)}<span>%</span></div><div class="metric-caption">${m.tp} events in ${m.tp+m.fp} flagged group-days</div></div><div class="metric"><div class="metric-label">Recall at frozen threshold</div><div class="metric-value">${num(100*m.recall,1)}<span>%</span></div><div class="metric-caption">${m.tp} detected / ${m.events} observed events</div></div></div>
    <section class="panel section-gap"><div class="panel-header"><div><h2>Beat the baseline. Show the misses.</h2><p>Identical test rows for all three strategies · lower Brier score is better</p></div><span class="tag">${m.n.toLocaleString('en-US')} TEST ROWS</span></div><div class="table-scroll"><table><thead><tr><th>STRATEGY</th><th>BRIER ↓</th><th>ROC AUC ↑</th><th>AVG. PRECISION ↑</th><th>PRECISION</th><th>RECALL</th><th>F1</th></tr></thead><tbody>${[['logistic','Logistic model'],['seasonal','Seasonal baseline'],['constant','Constant baseline']].map(([key,label])=>{const x=F.test[key];return `<tr><td><b>${label}</b></td><td>${num(x.brier,4)}</td><td>${num(x.rocAuc,3)}</td><td>${num(x.averagePrecision,3)}</td><td>${num(100*x.precision,1)}%</td><td>${num(100*x.recall,1)}%</td><td>${num(x.f1,3)}</td></tr>`;}).join('')}</tbody></table></div><div class="prose"><p class="note">Brier improvement (baseline minus model): ${num(ci.estimate,4)}; descriptive 95% moving-block bootstrap interval ${num(ci.lower,4)}–${num(ci.upper,4)}. ${ci.resamples} resamples of ${ci.blockCalendarDays}-day blocks keep all groups together. This does not establish performance in unseen regions.</p></div></section>
    <div class="results-grid section-gap"><section class="panel"><div class="panel-header"><div><h2>What the decision threshold costs</h2><p>Threshold ${num(100*m.threshold,2)}%, selected only on 2025 validation F1</p></div></div><div class="prose"><div class="confusion-grid"><div class="correct"><span>True positives</span><b>${m.tp}</b><small>Event correctly flagged</small></div><div><span>False positives</span><b>${m.fp}</b><small>Flagged, below 10 mm</small></div><div><span>False negatives</span><b>${m.fn}</b><small>Event missed</small></div><div class="correct"><span>True negatives</span><b>${m.tn.toLocaleString('en-US')}</b><small>Correctly below threshold</small></div></div><p class="note">About ${num(100*(1-m.recall),1)}% of events are missed. The threshold is a demonstration choice, not an operational safety policy.</p></div></section>
    <section class="panel"><div class="panel-header"><div><h2>Inspect an individual prediction</h2><p>Frozen 2026 test predictions; no future data enters the features</p></div></div><div class="prose"><div class="forecast-select"><label for="forecast-group">Weather group<select id="forecast-group">${groups.map(g=>`<option value="${g.group}" ${g.group===S.forecastGroup?'selected':''}>${g.site.cityName} · group ${g.group+1}</option>`).join('')}</select></label><label for="forecast-date">Target date<input type="date" id="forecast-date" min="2026-01-01" max="2026-09-21" value="${S.forecastDate}"></label></div>${selected?`<div class="prediction-result"><span>Issued after ${dateLabel(selected[1])}</span><strong>${num(100*selected[5],1)}<small>% probability</small></strong><p>Seasonal baseline: ${num(100*selected[6],1)}%<br>Observed next-day rainfall: <b>${num(selected[3],2)} mm</b></p><span class="tag">${outcome.toUpperCase()}</span></div>`:'<div class="callout amber">No eligible prediction on this date: the target or one of the three feature days has missing weather. No values were imputed.</div>'}</div></section></div>
    <section class="panel section-gap"><div class="panel-header"><div><h2>Calibration and model interpretation</h2><p>Reliability bins describe the test set. Coefficients are associations, not causes.</p></div><a class="secondary" href="results/forecast_evaluation.svg" download>↓ Vector figure</a></div><a href="results/forecast_evaluation.png" target="_blank" rel="noopener"><img class="research-figure" src="results/forecast_evaluation.png" alt="Three panels show model and baseline Brier scores, probability reliability, and eight largest standardized model coefficients."></a><details class="prose"><summary>Read reliability-bin counts</summary><div class="table-scroll"><table><thead><tr><th>PREDICTED RANGE</th><th>ROWS</th><th>MEAN PROBABILITY</th><th>OBSERVED RATE</th></tr></thead><tbody>${F.reliability.logistic.map(x=>`<tr><td>${num(100*x.lower,0)}–${num(100*x.upper,0)}%</td><td>${x.count}</td><td>${x.count?num(100*x.meanPrediction,1)+'%':'—'}</td><td>${x.count?num(100*x.observedRate,1)+'%':'—'}</td></tr>`).join('')}</tbody></table></div></details></section>
    <section class="panel section-gap"><div class="panel-header"><div><h2>Performance varies over time</h2><p>Monthly test results, including months where the model underperforms</p></div><a class="secondary" href="results/forecast_monthly.csv" download>↓ Monthly data</a></div><div class="table-scroll"><table><thead><tr><th>MONTH</th><th>ROWS</th><th>EVENTS</th><th>MODEL BRIER</th><th>BASELINE BRIER</th><th>IMPROVEMENT</th></tr></thead><tbody>${F.monthly.map(x=>`<tr><td>${x.month}</td><td>${x.n}</td><td>${x.events}</td><td>${num(x.modelBrier,4)}</td><td>${num(x.seasonalBrier,4)}</td><td>${num(x.seasonalBrier-x.modelBrier,4)}</td></tr>`).join('')}</tbody></table></div></section>
    <div class="result-interpretation"><h3>A weather experiment, with a defined boundary</h3><p>The target is recorded rain, not contamination, ecological health or disease. Daily aggregates must be complete before issuance; their original publication latency has not been verified. The same 21 weather groups appear in training and test, and correlations remain. A prospective trial and independent regions are needed before operational use.</p><p><a href="docs/FORECAST_MODEL_CARD.md">Model card ↗</a> · <a href="docs/FORECAST_PROTOCOL.md">Pre-specified protocol ↗</a> · <a href="results/forecast_metrics.json" download>Full metrics and model parameters ↓</a></p></div>`;
  }

  function render(){
    document.documentElement.lang='en';
    const primary={evidence:'Evidence',impact:'Research summary',alerts:'City alerts',onehealth:'One Health context',operations:'Mission control',citizen:'Citizen observations',resilience:'Resilience planning'};
    const advanced={multihazard:'Multi-hazard lab',notebook:'Field notebook',overview:'Overview',events:'Event explorer',results:'Results lab',forecast:'1-day benchmark',plan:'Field planner',compare:'Compare sites'};
    const labels={...primary,...advanced};
    const titles={impact:'Research bulletin',alerts:'Historical alert verification',onehealth:'Site exposure context',resilience:'Resilience planning',citizen:'Citizen observations',operations:'Monitoring assignments',multihazard:'Forecast evaluation',notebook:'Field measurements',forecast:'Next-day rainfall benchmark',events:'Historical weather events',results:'Sampling coverage analysis',overview:'Monitoring network',plan:'Field sampling plan',compare:'Site comparison',evidence:'Evidence and limits'};
    const nav=items=>Object.entries(items).map(([k,label])=>`<button data-action="navigate" data-page="${k}" class="${S.page===k?'active':''}" ${S.page===k?'aria-current="page"':''}>${label}</button>`).join('');
    const tour=v4.tourStep===null?'':`<section class="v4-tour" aria-label="Guided tour"><div><b>${R.tour[v4.tourStep][1]}</b><p>${R.tour[v4.tourStep][2]}</p></div><div>${v4.tourStep>0?'<button class="secondary" data-action="v4-tour-prev">← Back</button>':''}<button class="primary" data-action="v4-tour-next">${v4.tourStep===4?'Finish →':'Next →'}</button><button class="secondary" data-action="v4-tour-exit">Exit tour</button></div></section>`;
    const content=['impact','alerts','onehealth','resilience','citizen'].includes(S.page)?R.render(S.page,D,M,v4,citizenRecords):S.page==='operations'?W.operation(D,M,mission):S.page==='multihazard'?W.lab(D,M,mission):S.page==='notebook'?W.notebook(D,mission,observations):S.page==='overview'?overview():S.page==='events'?eventsView():S.page==='results'?resultsView():S.page==='forecast'?forecastView():S.page==='plan'?planView():S.page==='compare'?compareView():evidenceView();
    $('app').innerHTML=`<div class="shell"><aside class="sidebar"><div class="brand"><img src="assets/icon.svg" alt=""><div>StreamSignal<small>River monitoring bulletin</small></div></div><nav aria-label="Main navigation"><div class="nav-label">CORE WORKFLOW</div><div class="nav">${nav(primary)}</div><details class="v4-advanced" ${advanced[S.page]?'open':''}><summary>Advanced · evidence & tools</summary><div class="nav">${nav(advanced)}</div></details></nav><div class="sidebar-bottom">OneAquaHealth · Track 6</div></aside><div class="workspace"><header class="topbar"><div class="breadcrumb">Research workspace / <strong>${labels[S.page]}</strong></div><span class="tag hide-small">Historical replay</span></header><main id="main">${tour}<div class="hero"><div><div class="eyebrow">ONEAQUAHEALTH / RESILIENCE INFORMATICS</div><h1>${titles[S.page]}</h1><p class="subtitle">Historical monitoring data and forecast evaluation.</p></div></div>${S.page==='multihazard'?window.StreamNWP.research(window.StreamNWPResearch):S.page==='impact'?window.StreamNWP.summary():''}${content}<footer class="footer"><p class="bulletin-stamp">Historical weather through 21 Sep 2026</p><p class="limits-link">Limits: <a href="#page=evidence" data-action="navigate" data-page="evidence">see Evidence</a></p></footer></main></div></div>`;
    window.StreamBulletin.present($('app'));
  }

  function selectCity(city){S.city=city;S.pageNo=0;if(city!=='all'&&siteFor(S.site).city!==city)S.site=cityRows()[0].site.code;}
  function setDate(index){S.date=Math.max(firstReplay,Math.min(D.dates.length-1,index));compute();S.pageNo=0;}
  function exportPlan(){const picked=C.plan(cityRows().filter(r=>!S.savedOnly||S.saved.includes(r.site.code)),S.budget,S.diversify);if(!picked.length){toast(('No eligible sites to export.'));return;}const heads=['rank','replay_date','site_code','site_name','city','latitude','longitude','weather_group','screening_index','priority','driver','rain_3d_mm','max_temperature_c','dry_days','rain_percentile','heat_percentile','dry_percentile','weather_complete','baseline_start','baseline_end','watch_threshold','review_threshold','one_per_weather_group','method','next_step','review_status','analyst_note'];download(`StreamSignal_field_plan_${D.dates[S.date]}.csv`,C.csv([heads,...picked.map((r,i)=>[i+1,r.date,r.site.code,r.site.name,r.site.cityName,r.site.lat,r.site.lon,r.site.group+1,num(r.score,3),r.level,r.driver,r.values.rain,r.values.heat,r.values.dry,r.scores.rain,r.scores.heat,r.scores.dry,r.complete,D.meta.baselineStart,D.meta.baselineEnd,S.thresholds.watch,S.thresholds.high,S.diversify,'max of seasonal midrank percentiles; +/-30 calendar days; retrospective, not validated hazard prediction','Human review of local conditions; consider a fresh sample',S.reviews[reviewKey(r.site.code)]?.status||'Not reviewed',S.reviews[reviewKey(r.site.code)]?.note||''])]));}
  function exportHistory(code){const s=siteFor(code);const rowsOut=[['site_code','site_name','date','weather_group',...D.meta.fields,'rain_3d_mm','dry_days','screening_index','priority','rain_percentile','heat_percentile','dry_percentile','baseline_n_rain','baseline_n_heat','baseline_n_dry','weather_complete','baseline_start','baseline_end','watch_threshold','review_threshold']];D.dates.forEach((date,i)=>{const r=i>=firstReplay?E.assess(s,i,S.thresholds):null;rowsOut.push([code,s.name,date,s.group+1,...D.series[s.group][i],E.derived[s.group][i].rain,E.derived[s.group][i].dry,r?.score??null,r?.level??'calibration period',r?.scores.rain??null,r?.scores.heat??null,r?.scores.dry??null,r?.counts.rain??null,r?.counts.heat??null,r?.counts.dry??null,r?.complete??null,D.meta.baselineStart,D.meta.baselineEnd,S.thresholds.watch,S.thresholds.high]);});download(`StreamSignal_${code}_history.csv`,C.csv(rowsOut));}
  document.addEventListener('click',event=>{
    const el=event.target.closest('[data-action^="v4-"]');if(!el||el.disabled)return;
    const action=el.dataset.action;
    const htmlDoc=text=>`<!doctype html><html lang="en"><meta charset="utf-8"><title>StreamSignal local draft</title><style>body{font:16px/1.7 system-ui;max-width:850px;margin:40px auto;padding:20px;color:#102d45}pre{white-space:pre-wrap}</style><h1>StreamSignal · local draft</h1><pre>${esc(text)}</pre></html>`;
    if(action==='v4-timeline-export'){exportRows('StreamSignal_alert_timeline.csv',R.timeline(D,M,v4).map(r=>({...r,city:v4.city,hazard:v4.hazard,horizon:v4.horizon,red_threshold_pct:v4.red,provenance:'Historical weather replay; overlapping forecast windows'})));return;}
    if(action==='v4-draft-export'){download('StreamSignal_warning_draft.html',htmlDoc(R.alertDraft(D,M,v4)),'text/html;charset=utf-8');return;}
    if(action==='v4-task-export'){download('StreamSignal_citizen_task.html',htmlDoc(R.citizenTask(D,M,v4)),'text/html;charset=utf-8');return;}
    if(action==='v4-citizen-export'){exportRows('StreamSignal_citizen_observations.csv',citizenRecords);return;}
    if(action==='v4-mapping-export'){exportRows('StreamSignal_citizen_field_mapping.csv',R.mapping());return;}
    if(action==='v4-matrix-export'){const rows=R.matrix(D),valid=rows.filter(r=>r.sensitivity!==null),mx=R.median(valid.map(r=>r.exposure)),my=R.median(valid.map(r=>r.sensitivity));exportRows('StreamSignal_vulnerability_matrix.csv',rows.map(r=>({site:r.site.code,city:r.site.cityName,weather_group:r.site.group+1,exposure_pct:r.exposure,sensitivity:r.sensitivity,observed_days:r.n,rain_days:r.rain,heat_days:r.heat,above_both_medians:r.sensitivity===null?'Unscored':r.exposure>=mx&&r.sensitivity>=my,period_start:'2025-01-01',period_end:D.meta.weatherEnd,provenance:'Exploratory historical index; not damage or health prediction'})));return;}
    if(action==='v4-timeline-prev')v4.timelinePage=Math.max(0,v4.timelinePage-1);
    else if(action==='v4-timeline-next')v4.timelinePage++;
    else if(action==='v4-site'){v4.site=el.dataset.code;S.page='onehealth';}
    else if(action==='v4-to-mission'){mission.issue=v4.issue;mission.task='rain_3';mission.region=v4.city;mission.cut=v4.red;mission.recordSite=v4.site;S.page='operations';}
    else if(action==='v4-tour-start'){v4.tourStep=0;v4.issue='2026-02-02';v4.hazard='rain';v4.city='CO';v4.site='C2';v4.yellow=20;v4.red=40;mission.issue=v4.issue;mission.task='rain_3';mission.cut=30;mission.region='all';mission.budget=5;mission.distinct=true;mission.weight=0;S.page=R.tour[0][0];}
    else if(action==='v4-tour-prev'){v4.tourStep=Math.max(0,v4.tourStep-1);S.page=R.tour[v4.tourStep][0];}
    else if(action==='v4-tour-next'){if(v4.tourStep===4){v4.tourStep=null;S.page='impact';}else{v4.tourStep++;S.page=R.tour[v4.tourStep][0];if(v4.tourStep===2){mission.issue=v4.issue;mission.task=v4.hazard+'_3';mission.region=v4.city;mission.cut=v4.red;}}}
    else if(action==='v4-tour-exit')v4.tourStep=null;
    else return;
    render();if(!action.startsWith('v4-timeline'))window.scrollTo({top:0,behavior:'instant'});
  });
  document.addEventListener('change',event=>{
    const el=event.target,key=el.dataset.v4;if(!key)return;
    v4[key]=['yellow','red','horizon'].includes(key)?Number(el.value):el.value;
    if(key==='city')v4.site=D.sites.find(s=>s.city===v4.city).code;
    if(key==='hazard'&&!R.commonDates(M,v4.hazard).includes(v4.issue))v4.issue=R.commonDates(M,v4.hazard).at(-1);
    v4.timelinePage=0;render();
  });
  document.addEventListener('submit',event=>{
    if(event.target.id!=='citizen-form')return;event.preventDefault();const r=Object.fromEntries(new FormData(event.target));
    const error=R.validateCitizen(r,D);if(error){$('citizen-error').textContent=error;return;}
    Object.assign(r,{historical_issue:v4.issue,weather_target:v4.hazard,weather_group:D.sites.find(s=>s.code===r.site).group+1,provenance:'User-entered local observation; historical task cue; not model output',recorded_at:new Date().toISOString(),official_app_compatibility:'Concept alignment only; import schema unverified'});
    citizenRecords.push(r);try{localStorage.setItem('streamsignal.citizen.v4',JSON.stringify(citizenRecords));}catch{citizenRecords.pop();$('citizen-error').textContent='Storage unavailable. Copy your observation before leaving.';return;}
    render();toast('Observation saved locally. Nothing was sent.');
  });
  document.addEventListener('click',event=>{const el=event.target.closest('[data-action]');if(!el||el.disabled)return;const a=el.dataset.action;let top=false;if(a==='edit-observation'){mission.editRecord=Number(el.dataset.index);S.page='notebook';top=true;}else if(a==='cancel-observation-edit'){mission.editRecord=null;}else if(a==='archive-observation'||a==='restore-observation'){const index=Number(el.dataset.index);if(!observations[index])return;const old=observations[index].archived;observations[index].archived=a==='archive-observation';if(!saveObservations()){observations[index].archived=old;toast('Browser storage is unavailable.');return;}mission.editRecord=null;}else if(a==='multi-task'){setMissionTask(el.dataset.task);S.page='multihazard';top=true;}else if(a==='record-site'){mission.recordSite=el.dataset.code;mission.editRecord=null;S.page='notebook';top=true;}else if(a==='mission-export'){const output=W.exportRows(D,M,mission);if(!output.length){toast('No eligible visits under these settings.');return;}exportRows('StreamSignal_mission_'+mission.issue+'.csv',output);return;}else if(a==='mission-brief'){download('StreamSignal_investigation_'+mission.issue+'.html',W.brief(D,M,mission),'text/html;charset=utf-8');return;}else if(a==='observations-export'){if(!observations.some(r=>!r.archived)){toast('No active local observations to export.');return;}exportRows('StreamSignal_field_observations.csv',observations.filter(r=>!r.archived).map(r=>({site:r.site,observation_date:r.date,water_temperature_c:r.temperature,dissolved_oxygen_mg_l:r.oxygen,ph:r.ph,turbidity_ntu:r.turbidity,conductivity_us_cm:r.conductivity,method:r.method,notes:r.notes,provenance:r.provenance,recorded_at:r.recordedAt,updated_at:r.updatedAt||''})));return;}else if(a==='close-export'){closeExport();return;}else if(a==='result-period'){S.resultStart=el.dataset.period==='2026'?'2026-01-01':D.meta.replayStart;S.resultEnd=el.dataset.period==='2025'?'2025-12-31':D.meta.weatherEnd;S.eventPage=0;}else if(a==='analysis-report'){download('StreamSignal_analysis_report.html',window.StreamReports.analysis(getResults()),'text/html;charset=utf-8');return;}else if(a==='results-csv'){exportRows('StreamSignal_daily_comparison.csv',getResults().daily);return;}else if(a==='monthly-csv'){exportRows('StreamSignal_monthly_screening.csv',getResults().monthly);return;}else if(a==='groups-csv'){exportRows('StreamSignal_weather_groups.csv',getResults().groups);return;}else if(a==='events-csv'){exportRows('StreamSignal_screening_episodes.csv',eventList());return;}else if(a==='open-extreme'){const x=getResults().extremes[el.dataset.metric];if(x){showObservation(x.group,x.date,x.metric);top=true;}}else if(a==='open-episode'){const e=getResults().episodes.find(e=>e.id===el.dataset.episode);if(e){showObservation(e.group,e.peakDate,e.driver);top=true;}}else if(a==='group-focus'){const site=D.sites.find(s=>s.group===Number(el.dataset.group));showObservation(site.group,D.dates[S.date]);top=true;}else if(a==='event-prev'){S.eventPage--;}else if(a==='event-next'){S.eventPage++;}else if(a==='field-brief'){const picked=C.plan(cityRows().filter(r=>!S.savedOnly||S.saved.includes(r.site.code)),S.budget,S.diversify);if(!picked.length){toast('No eligible sites to export.');return;}download('StreamSignal_field_brief_'+D.dates[S.date]+'.html',window.StreamReports.field(picked,D.dates[S.date],S.reviews,D.meta),'text/html;charset=utf-8');return;}else if(a==='navigate'){S.page=el.dataset.page;top=true;}else if(a==='map-city'){selectCity(el.dataset.city);}else if(a==='all-regions'){selectCity('all');}else if(a==='select-site'){S.site=el.dataset.code;if(S.page!=='overview'){S.page='overview';S.city=siteFor(S.site).city;top=true;}}else if(a==='save-site'){const code=el.dataset.code;S.saved=S.saved.includes(code)?S.saved.filter(s=>s!==code):[...S.saved,code];persist();}else if(a==='prev-date'){setDate(S.date-1);}else if(a==='next-date'){setDate(S.date+1);}else if(a==='rain-replay'){let best={v:-1,index:firstReplay,site:rows[0].site};for(const site of D.sites.filter(s=>S.city==='all'||s.city===S.city)){for(let i=firstReplay;i<D.dates.length;i++){const v=E.derived[site.group][i].rain;if(v!==null&&v>best.v)best={v,index:i,site};}}setDate(best.index);S.site=best.site.code;toast(('Replaying the largest observed three-day rainfall in this region selection.'));}else if(a==='page-prev'){S.pageNo--;}else if(a==='page-next'){S.pageNo++;}else if(a==='chart'){S.chart=el.dataset.metric;}else if(a==='compare-open'){S.site=el.dataset.code;if(S.compare===S.site)S.compare=D.sites.find(s=>s.code!==S.site).code;S.page='compare';top=true;}else if(a==='site-export'){exportHistory(el.dataset.code);return;}else if(a==='plan-export'){exportPlan();return;}else if(a==='reset-thresholds'){S.thresholds={watch:85,high:95};compute();}else if(a==='audit-export'){download('StreamSignal_data_audit.json',JSON.stringify({meta:D.meta,groups:D.series.map((g,i)=>({group:i+1,sites:D.sites.filter(s=>s.group===i).map(s=>s.code)})),missingHealthSites:D.sites.filter(s=>!s.health.length).map(s=>s.code),missingNitrateSites:D.sites.filter(s=>!s.nitrate.length).map(s=>s.code)},null,2),'application/json');return;}else{return;}render();if(top)window.scrollTo({top:0,behavior:'instant'});});
  document.addEventListener('keydown',event=>{const el=event.target.closest('svg [role="button"]');if(el&&['Enter',' '].includes(event.key)){event.preventDefault();el.dispatchEvent(new MouseEvent('click',{bubbles:true}));}});
  document.addEventListener('change',event=>{const el=event.target,id=el.id;let changed=true;if(id==='mission-task'){setMissionTask(el.value);}else if(id==='mission-issue'){mission.issue=el.value;}else if(id==='mission-region'){mission.region=el.value;}else if(id==='mission-cut'){mission.cut=Number(el.value);}else if(id==='mission-budget'){mission.budget=Number(el.value);}else if(id==='mission-weight'){mission.weight=Number(el.value);}else if(id==='mission-distinct'){mission.distinct=el.checked;}else if(el.classList.contains('review-note')){const key=reviewKey(el.dataset.code);S.reviews[key]={...(S.reviews[key]||{}),note:el.value};persist();return;}else if(el.classList.contains('review-status')){const key=reviewKey(el.dataset.code);S.reviews[key]={...(S.reviews[key]||{}),status:el.value};persist();el.closest('details').querySelector('summary').textContent=el.value+' · Add a review note';toast('Review status saved locally.');return;}else if(id==='forecast-group'){S.forecastGroup=Number(el.value);}else if(id==='forecast-date'){if(el.value>='2026-01-01'&&el.value<='2026-09-21')S.forecastDate=el.value;}else if(id==='result-start'||id==='result-end'){const start=id==='result-start'?el.value:S.resultStart,end=id==='result-end'?el.value:S.resultEnd;if(start>end||!window.STREAM_REPLAY.dates.includes(start)||!window.STREAM_REPLAY.dates.includes(end)){toast('Choose an ordered date range within the replay period.');render();return;}S.resultStart=start;S.resultEnd=end;S.eventPage=0;}else if(id==='analysis-threshold'){S.thresholds.high=Number(el.value);if(S.thresholds.watch>=S.thresholds.high)S.thresholds.watch=S.thresholds.high-5;compute();S.eventPage=0;}else if(id==='event-metric'){S.eventMetric=el.value;S.eventPage=0;}else if(id==='event-sort'){S.eventSort=el.value;S.eventPage=0;}else if(id==='city'){selectCity(el.value);S.eventPage=0;}else if(id==='date'){const i=D.dates.indexOf(el.value);if(i<firstReplay){el.value=D.dates[S.date];toast(('Choose a replay date from 2025-01-01 to 2026-09-21.'));return;}setDate(i);}else if(id==='timeline'){setDate(Number(el.value));}else if(id==='level-filter'){S.filter=el.value;S.pageNo=0;}else if(id==='budget'){S.budget=Number(el.value);}else if(id==='diversify'){S.diversify=el.checked;}else if(id==='saved-only'){S.savedOnly=el.checked;}else if(id==='compare-a'){S.site=el.value;}else if(id==='compare-b'){S.compare=el.value;}else changed=false;if(changed)render();});
  document.addEventListener('input',event=>{const el=event.target;if(el.classList.contains('review-note')){const key=reviewKey(el.dataset.code);S.reviews[key]={...(S.reviews[key]||{}),note:el.value};persist();return;}else if(el.id==='search'){const pos=el.selectionStart;S.query=el.value;S.pageNo=0;render();$('search').focus();$('search').setSelectionRange(pos,pos);}else if(el.id==='timeline'){$('range-date').textContent=dateLabel(D.dates[Number(el.value)]);el.setAttribute('aria-valuetext',D.dates[Number(el.value)]);}});
  document.addEventListener('submit',event=>{if(event.target.id!=='observation-form')return;event.preventDefault();const f=new FormData(event.target),r={site:f.get('site'),date:f.get('date'),method:String(f.get('method')||'').trim(),notes:String(f.get('notes')||'').trim(),provenance:'User-entered local field record; not source data',recordedAt:new Date().toISOString()};for(const key of ['temperature','oxygen','ph','turbidity','conductivity'])r[key]=f.get(key)===''?null:Number(f.get(key));const error=W.validateObservation(r);if(error||!D.sites.some(s=>s.code===r.site)){$('observation-error').textContent=error||'Choose a valid research site.';return;}const editing=mission.editRecord!==null,previous=editing?observations[mission.editRecord]:null;if(editing){r.recordedAt=previous.recordedAt;r.updatedAt=new Date().toISOString();observations[mission.editRecord]=r;}else observations.push(r);if(!saveObservations()){if(editing)observations[mission.editRecord]=previous;else observations.pop();$('observation-error').textContent='Browser storage is unavailable. Copy your measurements before closing.';return;}mission.editRecord=null;render();toast('Observation saved locally. Models have not been updated.');});
  document.addEventListener('submit',event=>{if(event.target.id!=='threshold-form')return;event.preventDefault();const watch=Number($('watch-threshold').value),high=Number($('high-threshold').value);if(!Number.isInteger(watch)||!Number.isInteger(high)||watch<0||high>100||watch>=high){$('threshold-error').textContent=('Use whole numbers: 0 ≤ watch < review first ≤ 100.');return;}S.thresholds={watch,high};compute();render();toast(('Screening thresholds updated.'));});
  render();
})();
